const gen = $('Get Generation').first().json, magic = ($('Prompt Engine').first().json || {}).magic_prompt_json || {};
const tpl = $input.all().map((i) => i.json).find((r) => r.slug === 'qc_prompt');
if (!tpl || !tpl.body) throw new Error('no active qc_prompt template in prompt_templates');
// QC checks exactly the text the prompt asked for (the engine's text slot); the brief snapshot is the fallback
const src = Array.isArray((magic.text || {}).lines) ? magic.text.lines : ((gen.brief_snapshot && Array.isArray(gen.brief_snapshot.print_text)) ? gen.brief_snapshot.print_text : ((gen.cards && gen.cards.print_text) || []));
let lines = src.map((t) => String((t && t.text) || '').trim()).filter(Boolean);
if (!Array.isArray((magic.text || {}).lines) && gen.kind === 'edit_text' && gen.old_text && gen.new_text) lines = lines.map((l) => (l === String(gen.old_text).trim() ? String(gen.new_text).trim() : l));
const sc = gen.style_card_snapshot || {}, card = gen.cards || {}, es = magic.effective_style && typeof magic.effective_style === 'object' && !Array.isArray(magic.effective_style) ? magic.effective_style : null, rules = es ? Object.assign({}, es.rules && typeof es.rules === 'object' ? es.rules : sc.rules, /^(strict|flexible)$/.test(String(es.palette_mode || '')) ? { palette_mode: es.palette_mode } : {}) : (sc.rules || {}), imageUrl = $('Load Config').first().json.sbUrl + '/storage/v1' + String($('Sign Result').first().json.signedURL || '');
// the look QC judges = magic_prompt_json.effective_style when prompt-engine v8 sends it (source art_reference = the analysed Art style reference of the card wins - its medium, linework, shading, texture, edge finish and palette, palette_mode = the client strictness applied to that palette; source style_card = the Style Card values; its palette_mode drives PALETTE_RULE, its forbid the FORBID_LIST, and it also goes to qc-judge as style_card), else the Style Card snapshot as before (engine up to v7); qc_prompt v2 tokens: EXPECTED_SUBJECT = the engine's SUBJECT block; PALETTE_RULE from rules.palette_mode; FORBID_LIST numbered (only text demands dropped - @handles, social/media/instagram/ig/tiktok handles, hashtag/tagline/slogan, EST. + digits - as the style-card-check validator TEXT_DEMAND_RE does; negated visual bans such as No gradients, watermarks or a mug handle stay); STYLE_CARD_JSON pruned, palette = the palette_variants entry for the garment side
const side = /black|navy|charcoal|dark/i.test(String(card.garment_color || '')) ? 'dark' : 'light', variant = (Array.isArray(sc.palette_variants) ? sc.palette_variants : []).find((v) => v && v.garment === side);
const forbid = (es && Array.isArray(es.forbid) ? es.forbid : (Array.isArray(sc.forbid) ? sc.forbid : [])).map((f) => String(f || '').trim()).filter((f) => f && !/@\w+|\b(?:social|media|instagram|ig|tiktok)[\s-]+handles?\b|hashtag|tagline|slogan|\bEST\.?\s*\d/i.test(f));
const look = es || sc, pruned = Object.assign(es ? { source: es.source } : {}, { medium: look.medium, realism: look.realism, linework: look.linework, shading: look.shading, shading_method: look.shading_method, texture: look.texture, edge_finish: look.edge_finish, palette: es ? es.palette : (variant ? { garment: variant.garment, hexes: variant.hexes } : sc.palette), composition: look.composition, typography: look.typography, rules });
const paletteRule = es && es.source === 'art_reference' && !(Array.isArray(es.palette) && es.palette.length) ? 'always true - no colours were read from the Art style reference, so colours are not judged' : rules.palette_mode === 'flexible' ? 'true unless a LARGE, obvious area uses a colour clearly outside the palette - small natural accents are allowed' : 'true only when every colour in the artwork belongs to the palette or is a shade of one; small natural details count';
const artUrl = ''; // an edit is judged against its previous version - the Art style reference image is never attached here (ART_REFERENCE_ATTACHED no; WF-2 attaches it)
const vars = { EXPECTED_TEXT: lines.join('\n'), TEXT_LINES: lines.length ? lines.join('\n') : 'NONE', TEXT_LINES_JSON: JSON.stringify(lines), EXPECTED_SUBJECT: String((magic.subject || {}).text || (gen.brief_snapshot || {}).subject || (card.client_submission || {}).subject || ''), PALETTE_RULE: paletteRule, FORBID_LIST: forbid.map((f, i) => (i + 1) + '. ' + f).join('; ') || 'none', STYLE_CARD_JSON: JSON.stringify(pruned), PALETTE_JSON: JSON.stringify((es ? es.palette : sc.palette) || []), GARMENT_COLOR: card.garment_color || '', ART_REFERENCE_ATTACHED: artUrl ? 'yes' : 'no' };
let text = String(tpl.body).replace(/\{\{\s*([A-Z_]+)\s*\}\}/g, (m, k) => (k in vars ? vars[k] : m));
if (!lines.length) text = text.replace(/EXPECTED ON-DESIGN TEXT: """[\s\S]*?"""/, 'EXPECTED ON-DESIGN TEXT: (none - the image must contain NO text at all)'); // EXTRACT.md section 3.8: the template wraps {{EXPECTED_TEXT}} in triple quotes itself; with no text the WHOLE line is replaced
if (!/STYLE_CARD_JSON|PALETTE_JSON/.test(tpl.body)) text += '\n\nSTYLE CARD (the locked look for this client, JSON below). Add two keys to your JSON: "palette_ok" (' + paletteRule + ') and "style_violations" (array of short strings, [] when none: only a forbidden element from "forbid", or a palette problem). These style keys NEVER change "pass" or the 9 checks. Letter case, font and wording of the text are defined ONLY by the EXPECTED ON-DESIGN TEXT above - never report them as a violation.\n' + JSON.stringify(Object.assign({}, pruned, { forbid }));
if (!/EXPECTED_TEXT|TEXT_LINES/.test(tpl.body)) text += '\n\nEXACT TEXT LINES (each must appear verbatim, exactly once):\n' + vars.TEXT_LINES;
return { json: Object.assign({ body: { messages: [{ role: 'user', content: [{ type: 'text', text }, { type: 'image_url', image_url: { url: imageUrl } }].concat(artUrl ? [{ type: 'image_url', image_url: { url: artUrl } }] : []) }], response_format: { type: 'json_object' } }, text_lines: lines, expected_text: lines.join('\n'), expected_subject: vars.EXPECTED_SUBJECT, image_url: imageUrl, template_version: tpl.version, art_reference_attached: Boolean(artUrl) }, es ? { style_card: Object.assign({}, pruned, { forbid }) } : {}) };
